package au.monster.tracker;

import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.util.*;

public final class CatalogStore {
    private final Store store;
    public CatalogStore(Store store){this.store=store;}
    public record View(List<Catalog.Product> products,Map<String,Long> stock,List<Catalog.Shopping> shopping,Set<String> deleted){
        public List<Catalog.Product> activeProducts(){List<Catalog.Product> out=new ArrayList<>();for(var p:products)if(!deleted.contains(p.id()))out.add(p);return Ledger.copy(out);}
        public List<Catalog.Product> deletedProducts(){List<Catalog.Product> out=new ArrayList<>();for(var p:products)if(deleted.contains(p.id()))out.add(p);return Ledger.copy(out);}
        public List<Catalog.Shopping> activeShopping(){List<Catalog.Shopping> out=new ArrayList<>();for(var p:shopping)if(!deleted.contains(p.product().id()))out.add(p);return Ledger.copy(out);}
    }
    private static List<Catalog.Product> products(SQLiteDatabase db){List<Catalog.Product> out=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT p.id,p.name,s.body FROM products p JOIN product_settings s ON s.product_id=p.id ORDER BY p.rowid",null)){while(c.moveToNext()){var m=Purchases.map(Json.parse(c.getString(2)));out.add(new Catalog.Product(c.getString(0),Catalog.displayName(m,c.getString(1)),Purchases.num(m,"minimum"),Purchases.num(m,"target"),Purchases.num(m,"packSize"),Purchases.num(m,"packCost"),Purchases.str(m,"supplier")));}}return Ledger.copy(out);}
    private static Map<String,List<Catalog.Allocation>> allocations(SQLiteDatabase db){Map<String,List<Catalog.Allocation>> result=new HashMap<>();try(Cursor c=db.rawQuery("SELECT event_id,product_id,quantity FROM event_products ORDER BY rowid",null)){while(c.moveToNext())result.computeIfAbsent(c.getString(0),key->new ArrayList<>()).add(new Catalog.Allocation(c.getString(1),c.getLong(2)));}return result;}
    private static List<Catalog.Transfer> transfers(SQLiteDatabase db){List<Catalog.Transfer> result=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT body FROM flavour_transfers ORDER BY rowid",null)){while(c.moveToNext())result.add(Catalog.transfer(Json.parse(c.getString(0))));}return result;}
    static Map<String,Long> reserved(Store store){Ledger.Event pending=store.checkout();if(pending==null)return Collections.emptyMap();SQLiteDatabase db=store.database();try(Cursor existing=db.rawQuery("SELECT 1 FROM events WHERE id=?",new String[]{pending.id()})){if(existing.moveToFirst())return Collections.emptyMap();}List<Catalog.Allocation> values=Ledger.list(new Catalog.Allocation(Catalog.LEGACY,pending.quantity()));try(Cursor c=db.rawQuery("SELECT body FROM catalog_plans WHERE event_id=?",new String[]{pending.id()})){if(c.moveToFirst())values=Catalog.allocations(Json.parse(c.getString(0)));}Map<String,Long> result=new HashMap<>();for(var a:values)result.put(a.productId(),a.quantity());return result;}
    public View view(){synchronized(store){var db=store.database();var snapshot=store.snapshot();var qty=Catalog.stock(snapshot.events(),allocations(db),transfers(db));for(var held:reserved(store).entrySet())qty.put(held.getKey(),qty.getOrDefault(held.getKey(),0L)-held.getValue());var products=products(db);var documents=new BusinessStore(store).view();Map<String,Long> ordered=new HashMap<>();for(var d:documents.documents())if(!documents.cancelled().contains(d.id()))for(var l:d.lines())if(l.stock()&&l.productId()!=null)ordered.put(l.productId(),ordered.getOrDefault(l.productId(),0L)+l.cans()-documents.received().getOrDefault(l.id(),0L));List<Catalog.Shopping> shopping=new ArrayList<>();for(var p:products){long onHand=qty.getOrDefault(p.id(),0L);if(onHand<0)Purchases.bad("Historical flavour mapping needs reconciliation; no records were cleared.");shopping.add(Catalog.shopping(p,onHand,ordered.getOrDefault(p.id(),0L)));}return new View(products,Collections.unmodifiableMap(qty),Ledger.copy(shopping),Collections.unmodifiableSet(deletedIds(db)));}}
    public Catalog.Product lookupIncludingDeleted(String code){synchronized(store){String value=Catalog.barcode(code);String id;try(Cursor c=store.database().rawQuery("SELECT product_id FROM barcodes WHERE code=?",new String[]{value})){if(!c.moveToFirst())return null;id=c.getString(0);}for(var p:products(store.database()))if(p.id().equals(id))return p;return null;}}
    public Catalog.Product lookup(String code){synchronized(store){var p=lookupIncludingDeleted(code);return p==null||deletedIds(store.database()).contains(p.id())?null:p;}}
    private static Set<String> deletedIds(SQLiteDatabase db){Set<String> ids=new HashSet<>();try(Cursor c=db.rawQuery("SELECT product_id,body FROM product_settings",null)){while(c.moveToNext())if(Catalog.deleted(Purchases.map(Json.parse(c.getString(1)))))ids.add(c.getString(0));}return ids;}
    static void requireActive(SQLiteDatabase db,String id){try(Cursor c=db.rawQuery("SELECT body FROM product_settings WHERE product_id=?",new String[]{id})){if(!c.moveToFirst())Purchases.bad("Flavour does not exist.");if(Catalog.deleted(Purchases.map(Json.parse(c.getString(0)))))Purchases.bad("This flavour was deleted. Restore it from Deleted flavours before using it.");}}
    private static void deletion(SQLiteDatabase db,String id,boolean deleted,String action){Map<String,Object> settings;String name;try(Cursor c=db.rawQuery("SELECT s.body,p.name FROM product_settings s JOIN products p ON p.id=s.product_id WHERE p.id=?",new String[]{id})){if(!c.moveToFirst())throw new IllegalArgumentException("Flavour does not exist.");settings=Purchases.map(Json.parse(c.getString(0)));name=Catalog.displayName(settings,c.getString(1));}if(Catalog.deleted(settings)==deleted)return;if(deleted)settings.put("deleted",true);else settings.remove("deleted");ContentValues row=new ContentValues();row.put("body",Json.write(settings));db.update("product_settings",row,"product_id=?",new String[]{id});Map<String,Object> payload=new LinkedHashMap<>();payload.put("name",name);payload.put("deleted",deleted);audit(db,action,id,payload);}
    public void remove(String id){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{
        if(Catalog.LEGACY.equals(id))Purchases.bad("The unassigned historical flavour must be retained.");
        if(deletedIds(db).contains(id)){db.setTransactionSuccessful();return;}
        requireActive(db,id);if(store.hasPendingSave())Purchases.bad("A local save is still finishing. Finish that save before deleting a flavour.");
        if(reserved(store).getOrDefault(id,0L)>0)Purchases.bad("This flavour has a pending Stripe payment. Resolve it before deleting the flavour.");
        var state=view();if(state.stock().getOrDefault(id,0L)!=0)Purchases.bad("This flavour still has stock. Transfer or record the actual stock adjustment before deleting it.");
        for(var row:state.shopping())if(row.product().id().equals(id)&&row.ordered()>0)Purchases.bad("This flavour has unreceived supplier goods. Receive or cancel the outstanding purchase first.");
        deletion(db,id,true,"product.deleted");db.setTransactionSuccessful();
    }finally{db.endTransaction();}}}
    private static void uniqueName(SQLiteDatabase db,String id,String name){for(var p:products(db))if(!p.id().equals(id)&&p.name().equalsIgnoreCase(name))Purchases.bad("Another flavour already uses that name, including Deleted flavours. Choose a different name or restore the existing flavour.");}
    public void rename(String id,String value){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{
        if(Catalog.LEGACY.equals(id))Purchases.bad("The unassigned historical flavour must keep its name.");
        requireActive(db,id);String name=Catalog.displayName(Map.of("displayName",value==null?"":value),"");uniqueName(db,id,name);
        Map<String,Object> settings;String before;try(Cursor c=db.rawQuery("SELECT s.body,p.name FROM product_settings s JOIN products p ON p.id=s.product_id WHERE p.id=?",new String[]{id})){if(!c.moveToFirst())throw new IllegalArgumentException("Flavour does not exist.");settings=Purchases.map(Json.parse(c.getString(0)));before=Catalog.displayName(settings,c.getString(1));}
        if(!before.equals(name)){settings.put("displayName",name);ContentValues row=new ContentValues();row.put("body",Json.write(settings));db.update("product_settings",row,"product_id=?",new String[]{id});Map<String,Object> payload=new LinkedHashMap<>();payload.put("before",before);payload.put("after",name);audit(db,"product.renamed",id,payload);}
        db.setTransactionSuccessful();
    }finally{db.endTransaction();}}}
    public void restoreProduct(String id){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{deletion(db,id,false,"product.restored");db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    // Returned goods, an undo, or merged backup records can make an old flavour usable again.
    // Restore its visibility in the same transaction so no physical stock is hidden.
    void restoreNeeded(){synchronized(store){if(deletedIds(store.database()).isEmpty())return;var state=view();for(var row:state.shopping())if(state.deleted().contains(row.product().id())&&(row.onHand()>0||row.ordered()>0||reserved(store).getOrDefault(row.product().id(),0L)>0))deletion(store.database(),row.product().id(),false,"product.restored_stock");}}
    private static Map<String,Object> preferences(Catalog.Product p){Map<String,Object> m=new LinkedHashMap<>();m.put("minimum",p.minimum());m.put("target",p.target());m.put("packSize",p.packSize());m.put("packCost",p.packCost());m.put("supplier",p.supplier());m.put("displayName",p.name());return m;}
    private static void audit(SQLiteDatabase db,String action,String entity,Map<String,Object> body){long now=System.currentTimeMillis();ContentValues v=new ContentValues();v.put("id",Ledger.id());v.put("recorded_at",now);v.put("occurred_at",now);v.put("action",action);v.put("entity_id",entity);v.put("payload",Json.write(body));db.insertOrThrow("audit",null,v);}
    public void save(Catalog.Product product){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{String old=null;try(Cursor c=db.rawQuery("SELECT name FROM products WHERE id=?",new String[]{product.id()})){if(c.moveToFirst())old=c.getString(0);}if(old==null){uniqueName(db,product.id(),product.name());ContentValues v=new ContentValues();v.put("id",product.id());v.put("name",product.name());db.insertOrThrow("products",null,v);}else {requireActive(db,product.id());for(var p:products(db))if(p.id().equals(product.id())&&!p.name().equals(product.name()))Purchases.bad("Use Rename flavour to change its name.");}ContentValues settings=new ContentValues();settings.put("product_id",product.id());settings.put("body",Json.write(preferences(product)));db.insertWithOnConflict("product_settings",null,settings,SQLiteDatabase.CONFLICT_REPLACE);Map<String,Object> payload=new LinkedHashMap<>(preferences(product));payload.put("name",product.name());audit(db,"product.preferences",product.id(),payload);db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    public void assign(String code,String productId,boolean replace){synchronized(store){String value=Catalog.barcode(code);SQLiteDatabase db=store.database();db.beginTransaction();try{requireActive(db,productId);Catalog.Product old=lookupIncludingDeleted(value);if(old!=null&&!old.id().equals(productId)&&!replace)Purchases.bad("Barcode already belongs to "+old.name()+". Confirm reassignment explicitly.");if(old!=null&&old.id().equals(productId)){db.setTransactionSuccessful();return;}ContentValues v=new ContentValues();v.put("code",value);v.put("product_id",productId);db.insertWithOnConflict("barcodes",null,v,SQLiteDatabase.CONFLICT_REPLACE);Map<String,Object> m=new LinkedHashMap<>();m.put("code",value);m.put("previousProduct",old==null?null:old.id());m.put("productId",productId);audit(db,"barcode.assignment",productId,m);db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    public void transfer(Catalog.Transfer t){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{try(Cursor c=db.rawQuery("SELECT body FROM flavour_transfers WHERE id=?",new String[]{t.id()})){if(c.moveToFirst()){var existing=Catalog.transfer(Json.parse(c.getString(0)));var requested=new Catalog.Transfer(t.id(),t.from(),t.to(),t.quantity(),t.recordedAt(),t.note(),t.afterEventId()==null?existing.afterEventId():t.afterEventId());if(!existing.equals(requested))Purchases.bad("Conflicting transfer ID.");db.setTransactionSuccessful();return;}}if(store.hasPendingSave())Purchases.bad("A local save is still finishing. Reopen the tracker to recover it before transferring stock.");requireActive(db,t.from());requireActive(db,t.to());var stock=view().stock();if(stock.getOrDefault(t.from(),0L)<t.quantity())Purchases.bad("Not enough stock in the source flavour.");Set<String> ids=new HashSet<>();for(var p:products(db))ids.add(p.id());if(!ids.contains(t.from())||!ids.contains(t.to()))Purchases.bad("Unknown flavour.");var events=store.snapshot().events();var anchored=new Catalog.Transfer(t.id(),t.from(),t.to(),t.quantity(),t.recordedAt(),t.note(),t.afterEventId()==null?events.get(events.size()-1).id():t.afterEventId());ContentValues v=new ContentValues();v.put("id",t.id());v.put("body",Json.write(Catalog.transferMap(anchored)));db.insertOrThrow("flavour_transfers",null,v);audit(db,"stock.flavour_transfer",t.id(),Catalog.transferMap(anchored));db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    public void stage(Ledger.Event event,String productId,boolean checkout){stage(event,productId,checkout,0);}public void stage(Ledger.Event event,String productId,boolean checkout,long actualGst){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{for(var existing:store.snapshot().events())if(existing.id().equals(event.id())){if(!Ledger.same(existing,event))Purchases.bad("Conflicting transaction ID.");var saved=Catalog.forEvent(existing,allocations(db));if(saved.size()!=1||!saved.get(0).productId().equals(productId))Purchases.bad("Conflicting transaction flavour.");db.setTransactionSuccessful();return;}requireActive(db,productId);plan(db,event,Ledger.list(new Catalog.Allocation(productId,event.quantity())));Ledger.validate(event,store.snapshot().events());beforeAppend(store,event,store.snapshot().events());FinanceStore.plan(db,event,actualGst);if(checkout)store.beginCheckout(event);else store.stage(event);db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    static void plan(SQLiteDatabase db,Ledger.Event event,List<Catalog.Allocation> value){Map<String,List<Catalog.Allocation>> map=new HashMap<>();map.put(event.id(),value);Catalog.forEvent(event,map);String json=Json.write(Catalog.allocationMaps(value));try(Cursor c=db.rawQuery("SELECT body FROM catalog_plans WHERE event_id=?",new String[]{event.id()})){if(c.moveToFirst()&&!c.getString(0).equals(json))Purchases.bad("Pending transaction flavour changed.");}ContentValues v=new ContentValues();v.put("event_id",event.id());v.put("body",json);db.insertWithOnConflict("catalog_plans",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
    static void beforeAppend(Store store,Ledger.Event event,List<Ledger.Event> current){SQLiteDatabase db=store.database();Map<String,List<Catalog.Allocation>> map=allocations(db);try(Cursor c=db.rawQuery("SELECT body FROM catalog_plans WHERE event_id=?",new String[]{event.id()})){if(c.moveToFirst())map.put(event.id(),Catalog.allocations(Json.parse(c.getString(0))));}List<Ledger.Event> trial=new ArrayList<>(current);trial.add(event);var stock=Catalog.stock(trial,map,transfers(db));var pending=store.checkout();if(pending!=null&&!pending.id().equals(event.id()))for(var held:reserved(store).entrySet())if(stock.getOrDefault(held.getKey(),0L)<held.getValue())Purchases.bad("Those cans are reserved for the pending Stripe payment. Other available stock can still be recorded offline.");for(var value:stock.values())if(value<0)Purchases.bad("Not enough stock in that flavour. Choose the correct flavour or correct its stock count.");Set<String> ids=new HashSet<>();for(var p:products(db))ids.add(p.id());for(var id:stock.keySet())if(!ids.contains(id))Purchases.bad("Flavour does not exist.");}
    static void afterAppend(Store store,Ledger.Event event){SQLiteDatabase db=store.database();try(Cursor c=db.rawQuery("SELECT body FROM catalog_plans WHERE event_id=?",new String[]{event.id()})){if(c.moveToFirst()){var values=Catalog.allocations(Json.parse(c.getString(0)));for(var a:values){ContentValues v=new ContentValues();v.put("event_id",event.id());v.put("product_id",a.productId());v.put("quantity",a.quantity());db.insertOrThrow("event_products",null,v);}Map<String,Object> payload=new LinkedHashMap<>();payload.put("eventId",event.id());payload.put("allocations",Catalog.allocationMaps(values));audit(db,"stock.flavour_event",event.id(),payload);db.delete("catalog_plans","event_id=?",new String[]{event.id()});}}new CatalogStore(store).restoreNeeded();}
    public Map<String,Object> export(){synchronized(store){SQLiteDatabase db=store.database();Set<String> removed=deletedIds(db);Map<String,String> originalNames=new HashMap<>();try(Cursor c=db.rawQuery("SELECT id,name FROM products",null)){while(c.moveToNext())originalNames.put(c.getString(0),c.getString(1));}Map<String,Object> out=new LinkedHashMap<>();List<Object> ps=new ArrayList<>();for(var p:products(db)){Map<String,Object> m=new LinkedHashMap<>(preferences(p));m.put("id",p.id());m.put("name",originalNames.get(p.id()));if(removed.contains(p.id()))m.put("deleted",true);ps.add(m);}out.put("products",ps);List<Object> bs=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT code,product_id FROM barcodes ORDER BY code",null)){while(c.moveToNext()){Map<String,Object> m=new LinkedHashMap<>();m.put("code",c.getString(0));m.put("productId",c.getString(1));bs.add(m);}}out.put("barcodes",bs);List<Object> rows=new ArrayList<>();for(var entry:allocations(db).entrySet()){Map<String,Object> m=new LinkedHashMap<>();m.put("eventId",entry.getKey());m.put("allocations",Catalog.allocationMaps(entry.getValue()));rows.add(m);}out.put("allocations",rows);List<Object> moves=new ArrayList<>();for(var t:transfers(db))moves.add(Catalog.transferMap(t));out.put("transfers",moves);return out;}}
    public void restore(Map<String,Object> data,List<Ledger.Event> events){if(data==null)return;CatalogBackup.validate(data,events);SQLiteDatabase db=store.database();for(Object value:Purchases.list(data.get("products"))){var m=Purchases.map(value);var p=CatalogBackup.product(m);String name=null,previousBody=null;try(Cursor c=db.rawQuery("SELECT p.name,s.body FROM products p JOIN product_settings s ON s.product_id=p.id WHERE p.id=?",new String[]{p.id()})){if(c.moveToFirst()){name=c.getString(0);previousBody=c.getString(1);}}
            Map<String,Object> incoming=preferences(p);if(m.containsKey("displayName"))incoming.put("displayName",Catalog.displayName(m,p.name()));else if(previousBody!=null){var existingSettings=Purchases.map(Json.parse(previousBody));if(existingSettings.containsKey("displayName"))incoming.put("displayName",Catalog.displayName(existingSettings,p.name()));}if(Catalog.deleted(m)||(previousBody!=null&&Catalog.deleted(Purchases.map(Json.parse(previousBody)))))incoming.put("deleted",true);String body=Json.write(incoming);
            if(name==null){ContentValues row=new ContentValues();row.put("id",p.id());row.put("name",p.name());db.insertOrThrow("products",null,row);ContentValues settings=new ContentValues();settings.put("product_id",p.id());settings.put("body",body);db.insertOrThrow("product_settings",null,settings);}
            else if(!name.equals(p.name()))Purchases.bad("Conflicting flavour identity. Restore cancelled.");
            else if(!previousBody.equals(body)){Map<String,Object> payload=new LinkedHashMap<>();payload.put("before",Json.parse(previousBody));payload.put("after",incoming);audit(db,"product.preferences_restore",p.id(),payload);ContentValues values=new ContentValues();values.put("body",body);db.update("product_settings",values,"product_id=?",new String[]{p.id()});}
        }
        Set<String> displayNames=new HashSet<>();for(var product:products(db))if(!displayNames.add(product.name().toLowerCase(Locale.ROOT)))Purchases.bad("Combined restore would create duplicate flavour names. Current records are unchanged.");
        for(Object value:Purchases.list(data.get("barcodes"))){var m=Purchases.map(value);Catalog.Product old=lookupIncludingDeleted(Purchases.str(m,"code"));String id=Purchases.str(m,"productId");if(old!=null&&!old.id().equals(id))Purchases.bad("Barcode conflict in restore.");if(old==null){ContentValues v=new ContentValues();v.put("code",Purchases.str(m,"code"));v.put("product_id",id);db.insertOrThrow("barcodes",null,v);}}
        for(Object value:Purchases.list(data.get("allocations"))){var m=Purchases.map(value);String eventId=Purchases.str(m,"eventId");List<Catalog.Allocation> incoming=Catalog.allocations(m.get("allocations"));var existing=allocations(db).get(eventId);if(existing!=null){if(!Json.write(Catalog.allocationMaps(existing)).equals(Json.write(Catalog.allocationMaps(incoming))))Purchases.bad("Historical flavour conflict. Nothing restored.");}else for(var a:incoming){ContentValues v=new ContentValues();v.put("event_id",eventId);v.put("product_id",a.productId());v.put("quantity",a.quantity());db.insertOrThrow("event_products",null,v);}}
        for(Object value:Purchases.list(data.get("transfers"))){var t=Catalog.transfer(value);String old=null;try(Cursor c=db.rawQuery("SELECT body FROM flavour_transfers WHERE id=?",new String[]{t.id()})){if(c.moveToFirst())old=c.getString(0);}String json=Json.write(Catalog.transferMap(t));if(old==null){ContentValues v=new ContentValues();v.put("id",t.id());v.put("body",json);db.insertOrThrow("flavour_transfers",null,v);}else if(!old.equals(json))Purchases.bad("Conflicting flavour transfer.");}var stock=Catalog.stock(events,allocations(db),transfers(db));for(long q:stock.values())if(q<0)Purchases.bad("Combined restore would make a flavour negative. Current records are unchanged.");
    }
}

